begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) select ('60000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'library-sql-'||n||'@example.invalid',jsonb_build_object('username','Library_SQL'||n) from generate_series(1,5) n;
insert into auth.sessions(id,user_id) select id,id from public.profiles where id::text like '60000000-%';
update private.authz set role='critic' where user_id='60000000-0000-0000-0000-000000000003';
update private.authz set role='moderator' where user_id='60000000-0000-0000-0000-000000000004';
update private.authz set role='admin' where user_id='60000000-0000-0000-0000-000000000005';
insert into public.manual_games(id,title,synopsis,platforms,genres,source_url,source_label) values('60000000-0000-0000-0000-000000000099','Isolated library SQL fixture','Isolated SQL test, never live provider data.',array['PC'],array['Test'],'https://example.com/isolated-library-sql','Isolated test');
insert into public.games(id,provider,external_id,document) values('rawg:99999999999','rawg',99999999999,'{"id":"rawg:99999999999","title":"Isolated persisted SQL"}');
select lives_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','create','{"gameId": "manual:60000000-0000-0000-0000-000000000099", "state": null, "favorite": false, "interested": false, "progress": null}'::jsonb)$$,'role 1 saves own entry');
select lives_ok($$select private.library_operation('60000000-0000-0000-0000-000000000003','60000000-0000-0000-0000-000000000003','create','{"gameId": "manual:60000000-0000-0000-0000-000000000099", "state": null, "favorite": false, "interested": false, "progress": null}'::jsonb)$$,'role 3 saves own entry');
select lives_ok($$select private.library_operation('60000000-0000-0000-0000-000000000004','60000000-0000-0000-0000-000000000004','create','{"gameId": "manual:60000000-0000-0000-0000-000000000099", "state": null, "favorite": false, "interested": false, "progress": null}'::jsonb)$$,'role 4 saves own entry');
select lives_ok($$select private.library_operation('60000000-0000-0000-0000-000000000005','60000000-0000-0000-0000-000000000005','create','{"gameId": "manual:60000000-0000-0000-0000-000000000099", "state": null, "favorite": false, "interested": false, "progress": null}'::jsonb)$$,'role 5 saves own entry');
select lives_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','create','{"gameId": "rawg:99999999999", "state": null, "favorite": false, "interested": false, "progress": null}'::jsonb)$$,'persisted RAWG entry');
select throws_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','create','{"gameId": "manual:60000000-0000-0000-0000-000000000099", "state": null, "favorite": false, "interested": false, "progress": null}'::jsonb)$$,'23505',null,'duplicate blocked');
select throws_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','update','{"gameId": "manual:60000000-0000-0000-0000-000000000099", "state": null, "favorite": false, "interested": false, "progress": null, "id": null, "version": 1}'::jsonb)$$,'22023',null,'update null id rejected');
select throws_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','update','{"gameId": "manual:60000000-0000-0000-0000-000000000099", "state": null, "favorite": false, "interested": false, "progress": null, "id": "60000000-0000-0000-0000-000000000099", "version": null}'::jsonb)$$,'22023',null,'update null version rejected');
select throws_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','remove','{"gameId": "manual:60000000-0000-0000-0000-000000000099", "id": null, "version": 1}'::jsonb)$$,'22023',null,'remove null id rejected');
select throws_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','remove','{"gameId": "manual:60000000-0000-0000-0000-000000000099", "id": "60000000-0000-0000-0000-000000000099", "version": null}'::jsonb)$$,'22023',null,'remove null version rejected');
create temporary table library_before as select * from public.user_library where user_id='60000000-0000-0000-0000-000000000001' and manual_game_id is not null;
select lives_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','update',jsonb_build_object('gameId','manual:60000000-0000-0000-0000-000000000099','id',id,'version',version,'state','playing','favorite',true,'interested',false,'progress',23)) from library_before$$,'independent marks update');
select throws_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','remove',jsonb_build_object('gameId','manual:60000000-0000-0000-0000-000000000099','id',id,'version',version)) from library_before$$,'23505',null,'stale version denied');
select lives_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','remove',jsonb_build_object('gameId','manual:60000000-0000-0000-0000-000000000099','id',id,'version',version+1)) from library_before$$,'remove current version');
select lives_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','create','{"gameId": "manual:60000000-0000-0000-0000-000000000099", "state": null, "favorite": false, "interested": false, "progress": null}'::jsonb)$$,'re-add new entry');
select isnt((select id from public.user_library where user_id='60000000-0000-0000-0000-000000000001' and manual_game_id is not null),(select id from library_before),'new UUID prevents ABA');
select throws_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','remove',jsonb_build_object('gameId','manual:60000000-0000-0000-0000-000000000099','id',id,'version',1)) from library_before$$,'23505',null,'ABA old identity denied');
set local role anon;
select throws_ok($$insert into public.user_library(user_id) values(gen_random_uuid())$$,'42501',null,'anon direct mutation denied');
select throws_ok($$update public.user_library set favorite=true$$,'42501',null,'anon direct mutation denied');
select throws_ok($$delete from public.user_library$$,'42501',null,'anon direct mutation denied');
select throws_ok($$update public.private_user_settings set library_visibility='public'$$,'42501',null,'anon direct mutation denied');
reset role;
set local role authenticated;
select throws_ok($$insert into public.user_library(user_id) values(gen_random_uuid())$$,'42501',null,'authenticated direct mutation denied');
select throws_ok($$update public.user_library set favorite=true$$,'42501',null,'authenticated direct mutation denied');
select throws_ok($$delete from public.user_library$$,'42501',null,'authenticated direct mutation denied');
select throws_ok($$update public.private_user_settings set library_visibility='public'$$,'42501',null,'authenticated direct mutation denied');
reset role;
set local role service_role;
select throws_ok($$insert into public.user_library(user_id) values(gen_random_uuid())$$,'42501',null,'service_role direct mutation denied');
select throws_ok($$update public.user_library set favorite=true$$,'42501',null,'service_role direct mutation denied');
select throws_ok($$delete from public.user_library$$,'42501',null,'service_role direct mutation denied');
select throws_ok($$update public.private_user_settings set library_visibility='public'$$,'42501',null,'service_role direct mutation denied');
reset role;
select set_config('request.jwt.claims','{"sub":"60000000-0000-0000-0000-000000000001","session_id":"60000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.user_library where user_id='60000000-0000-0000-0000-000000000001'),2,'private RLS for role 1');
select is((select count(*)::int from public.private_user_settings where user_id='60000000-0000-0000-0000-000000000001'),1,'preferences private role 1');
reset role;
select set_config('request.jwt.claims','{"sub":"60000000-0000-0000-0000-000000000002","session_id":"60000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.user_library where user_id='60000000-0000-0000-0000-000000000001'),0,'private RLS for role 2');
select is((select count(*)::int from public.private_user_settings where user_id='60000000-0000-0000-0000-000000000001'),0,'preferences private role 2');
reset role;
select set_config('request.jwt.claims','{"sub":"60000000-0000-0000-0000-000000000003","session_id":"60000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.user_library where user_id='60000000-0000-0000-0000-000000000001'),0,'private RLS for role 3');
select is((select count(*)::int from public.private_user_settings where user_id='60000000-0000-0000-0000-000000000001'),0,'preferences private role 3');
reset role;
select set_config('request.jwt.claims','{"sub":"60000000-0000-0000-0000-000000000004","session_id":"60000000-0000-0000-0000-000000000004","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.user_library where user_id='60000000-0000-0000-0000-000000000001'),0,'private RLS for role 4');
select is((select count(*)::int from public.private_user_settings where user_id='60000000-0000-0000-0000-000000000001'),0,'preferences private role 4');
reset role;
select set_config('request.jwt.claims','{"sub":"60000000-0000-0000-0000-000000000005","session_id":"60000000-0000-0000-0000-000000000005","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.user_library where user_id='60000000-0000-0000-0000-000000000001'),0,'private RLS for role 5');
select is((select count(*)::int from public.private_user_settings where user_id='60000000-0000-0000-0000-000000000001'),0,'preferences private role 5');
reset role;
select lives_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','privacy','{"version": 1, "visibility": "public"}'::jsonb)$$,'explicit publish');
select set_config('request.jwt.claims','{}',true);
set local role anon;
select is((select count(*)::int from public.user_library),2,'anon sees only public owner');
reset role;
select throws_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','privacy','{"version": 1, "visibility": "private"}'::jsonb)$$,'23505',null,'privacy stale conflict');
select lives_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','privacy','{"version": 2, "visibility": "private"}'::jsonb)$$,'explicit privatize');
select set_config('request.jwt.claims','{}',true);
set local role anon;
select is((select count(*)::int from public.user_library),0,'new read hidden after privatize');
reset role;
select lives_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','privacy','{"version": 3, "visibility": "public"}'::jsonb)$$,'republish for suspension check');
update private.authz set status='suspended' where user_id='60000000-0000-0000-0000-000000000001';
select throws_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','own','{"gameId": "manual:60000000-0000-0000-0000-000000000099"}'::jsonb)$$,'42501',null,'suspended owner denied');
select set_config('request.jwt.claims','{}',true);
set local role anon;
select is((select count(*)::int from public.user_library),0,'suspension hides public library');
reset role;
update private.authz set status='active' where user_id='60000000-0000-0000-0000-000000000001';
delete from auth.sessions where id='60000000-0000-0000-0000-000000000001';
select throws_ok($$select private.library_operation('60000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001','own','{"gameId": "manual:60000000-0000-0000-0000-000000000099"}'::jsonb)$$,'42501',null,'revoked own read denied');
select * from finish();
rollback;
